'use strict';
const isPT=document.documentElement.lang==='pt-BR';
const copy=(en,pt)=>isPT?pt:en;
const option=(en,pt)=>`<option value="${escape(en)}">${escape(copy(en,pt))}</option>`;
// All opportunity amounts and probabilities below are made up for this sandbox.
const deals=[{id:1,name:'Data access pilot',company:'Harbor Retail Group',stage:'Discovery',amount:24000,probability:20,risk:'Priorities not yet validated',next:'Confirm the business questions',task:'Discovery workshop'}, {id:2,name:'Workflow automation',company:'Evergreen Manufacturing',stage:'Technical evaluation',amount:48000,probability:40,risk:'Integration scope is unclear',next:'Review integration requirements',task:'Technical alignment'}, {id:3,name:'Analytics enablement',company:'Cedar Health Network',stage:'Proposal',amount:36000,probability:60,risk:'Decision process not confirmed',next:'Validate scope with stakeholders',task:'Proposal review'}, {id:4,name:'AI governance discovery',company:'Meridian Financial',stage:'On hold',amount:18000,probability:0,risk:'Timing not confirmed',next:'Agree a future review date',task:'Review timing'}];
const stageOptions=()=>['Discovery','Technical evaluation','Proposal','On hold'].map(x=>option(x,{'Discovery':'Discovery','Technical evaluation':'Avaliação técnica','Proposal':'Proposta','On hold':'Em espera'}[x])).join('');
const money=v=>new Intl.NumberFormat(isPT?'pt-BR':'en-US',{style:'currency',currency:'USD',maximumFractionDigits:0}).format(v);
let pipelineTab=document.createElement('button');pipelineTab.id='tab-pipeline';pipelineTab.setAttribute('role','tab');pipelineTab.setAttribute('aria-selected','false');pipelineTab.setAttribute('aria-controls','view-pipeline');pipelineTab.textContent=copy('Opportunity lab','Laboratório de oportunidades');document.querySelector('.workspace [role=tablist]').append(pipelineTab);
let pipelineView=document.createElement('section');pipelineView.id='view-pipeline';pipelineView.setAttribute('role','tabpanel');pipelineView.setAttribute('aria-labelledby','tab-pipeline');pipelineView.hidden=true;pipelineView.innerHTML=`<div class="pipeline-intro"><h4>${copy('Practice the opportunity review','Explore a revisão de oportunidades')}</h4><p>${copy('Entirely fictional opportunities in USD. Edit a stage, risk, next step and probability to see how a weighted scenario changes. This is a teaching example, not a real forecast.','Oportunidades inteiramente fictícias em USD. Edite etapa, risco, próximo passo e probabilidade para ver como um cenário ponderado muda. É um exemplo demonstrativo, não um forecast real.')}</p></div><div id="pipeline-metrics" class="metrics"></div><div id="deal-list" class="deal-list"></div><p class="footnote">${copy('Weighted scenario = sum of illustrative amount × manually selected probability. It ignores timing, slippage and dependencies; it is not expected revenue. These controls do not update any CRM.','Cenário ponderado = soma de valor ilustrativo × probabilidade escolhida manualmente. Não considera prazo, adiamentos ou dependências; não representa receita esperada. Os controles não atualizam nenhum CRM.')}</p>`;document.querySelector('.workspace-main').append(pipelineView);
const previousTab=tab;tab=function(name){if(name==='pipeline'){document.querySelectorAll('.workspace [role=tabpanel]').forEach(x=>x.hidden=x.id!=='view-pipeline');document.querySelectorAll('.workspace [role=tab]').forEach(x=>x.setAttribute('aria-selected',String(x.id==='tab-pipeline')));$('#view-title').textContent=copy('Opportunity review','Revisão de oportunidades');$('#view-description').textContent=copy('Illustrative pipeline, decisions and next steps.','Pipeline ilustrativo, decisões e próximos passos.');renderDeals();}else{pipelineView.hidden=true;pipelineTab.setAttribute('aria-selected','false');previousTab(name);}document.querySelector('.filters').hidden=name==='pipeline';};pipelineTab.onclick=()=>tab('pipeline');
// All four tabs support keyboard navigation in their displayed order.
document.querySelector('.workspace [role=tablist]').addEventListener('keydown',e=>{if(!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;e.preventDefault();e.stopImmediatePropagation();const bs=[...document.querySelectorAll('.workspace [role=tab]')],i=bs.indexOf(document.activeElement);const n=e.key==='Home'?0:e.key==='End'?bs.length-1:(i+(e.key==='ArrowRight'?1:bs.length-1))%bs.length;const b=bs[n];tab(b.id.replace('tab-',''));b.focus();},true);
function renderDeals(){const total=deals.reduce((s,d)=>s+d.amount,0),weighted=deals.reduce((s,d)=>s+d.amount*d.probability/100,0);$('#pipeline-metrics').innerHTML=[[copy('Illustrative pipeline','Pipeline ilustrativo'),money(total)],[copy('Weighted scenario','Cenário ponderado'),money(weighted)],[copy('Fictional opportunities','Oportunidades fictícias'),deals.length]].map(([a,b])=>`<article class="metric"><span>${a}</span><strong>${b}</strong><small>${copy('Demo data only','Somente dados demonstrativos')}</small></article>`).join('');$('#deal-list').innerHTML=deals.map(d=>`<article class="deal"><div class="deal-heading"><div><h4>${escape(d.company)}</h4><p>${tr(d.name)}</p></div><strong>${money(d.amount)}</strong></div><div class="deal-fields"><label>${copy('Stage','Etapa')}<select data-deal="${d.id}" data-field="stage">${stageOptions()}</select></label><label>${copy('Probability (%)','Probabilidade (%)')}<input type="number" min="0" max="100" step="5" value="${d.probability}" data-deal="${d.id}" data-field="probability"></label><label>${copy('Main risk','Principal risco')}<input maxlength="180" value="${escape(tr(d.risk))}" data-deal="${d.id}" data-field="risk"></label><label>${copy('Next step','Próximo passo')}<input maxlength="180" value="${escape(tr(d.next))}" data-deal="${d.id}" data-field="next"></label></div></article>`).join('');for(const d of deals)document.querySelector(`[data-deal="${d.id}"][data-field=stage]`).value=d.stage;}
$('#deal-list').addEventListener('change',e=>{const el=e.target;if(!el.dataset.deal)return;const d=deals.find(x=>x.id===Number(el.dataset.deal)),f=el.dataset.field;if(f==='probability')d[f]=Math.max(0,Math.min(100,Number(el.value)||0));else d[f]=el.value.trim();renderDeals();});
$('#deal-list').addEventListener('input',e=>{const el=e.target;if(!el.dataset.deal)return;const d=deals.find(x=>x.id===Number(el.dataset.deal)),f=el.dataset.field;if(f==='probability'){d.probability=Math.max(0,Math.min(100,Number(el.value)||0));const value=deals.reduce((s,x)=>s+x.amount*x.probability/100,0);$('#pipeline-metrics').querySelectorAll('strong')[1].textContent=money(value);}else if(f==='risk'||f==='next')d[f]=el.value;});
const oldMessage=message;message=function(l){if(isPT)return`Olá, ${l.name.split(' ')[0]}, tudo bem?\n\nVi sua atuação como ${tr(l.role)} na ${l.company}. Gostaria de entender como sua área está trabalhando com ${tr(l.driver).toLowerCase().replace(/\bia\b/g,"IA")}.\n\nPosso compartilhar um exemplo e entender se o tema é uma prioridade para o seu time. Faz sentido uma conversa de discovery?\n\nAbraço,\nIgor`;return oldMessage(l);};
const originalDetail=detail;detail=function(){originalDetail();const l=leads.find(x=>x.id===activeLead);if(!l||guideState)return;const box=document.createElement('section');box.className='detail-block qualification-editor';box.innerHTML=`<h3>${copy('Try your own qualification','Experimente sua qualificação')}</h3><p>${copy('Change the outreach hypothesis and seniority to update the preview. This edits only fictional local demo data; it does not validate a real customer need.','Altere a hipótese de abordagem e a senioridade para atualizar a prévia. A edição afeta apenas dados fictícios locais; não valida uma necessidade real.')}</p><form id="qualification-form"><label>${copy('Driver hypothesis','Hipótese de abordagem')}<select id="edit-driver">${hypotheses.map(x=>option(x,tr(x))).join('')}</select></label><label>${copy('Seniority','Senioridade')}<select id="edit-seniority">${option('Director','Diretoria')}${option('Head / Manager','Head / Gerência')}${option('Specialist / Supervisor','Especialista / Supervisão')}</select></label><label>${copy('Your rationale','Sua justificativa')}<textarea id="edit-rationale" maxlength="400" rows="3" required></textarea></label><button class="primary" type="submit">${copy('Apply to demo preview','Aplicar na prévia')}</button><p id="qualification-status" role="status"></p></form>`;const first=$('#lead-detail .detail-block');first.after(box);$('#edit-driver').value=l.driver;$('#edit-seniority').value=l.seniority;$('#edit-rationale').value=tr(l.summary);$('#qualification-form').onsubmit=e=>{e.preventDefault();const s=$('#edit-rationale').value.trim();if(!s)return;l.driver=$('#edit-driver').value;l.seniority=$('#edit-seniority').value;l.summary=s;save();render();detail();$('#qualification-status').textContent=copy('Saved locally. The message preview now uses your selected driver.','Salvo localmente. A prévia da mensagem usa a hipótese escolhida.');};};
