function tr(s){if(!isPT)return String(s);s=String(s);if(dict[s])return dict[s];if(s.includes(' · '))return s.split(' · ').map(x=>tr(x)).join(' · ');return s.replace(/^(\d+)% of reached contacts$/,'$1% dos contatos alcançados').replace(/^(\d+) fictional contacts shown$/,'$1 contatos fictícios exibidos').replace(/^STEP (\d) OF 5( · ISOLATED DEMO)?$/,'ETAPA $1 DE 5 · DEMONSTRAÇÃO').replace(/^STEP (\d) OF 5$/,'ETAPA $1 DE 5').replace('ISOLATED DEMO','DEMONSTRAÇÃO ISOLADA').replace(/^TOUCH (\d)/,'ABORDAGEM $1').replace('AFTER A REPLY','APÓS UMA RESPOSTA').replace('A qualification hypothesis, contact history and next action.','Uma hipótese, histórico do contato e próxima ação.').replace('A consistent process that stops and adapts after a reply.','Um processo que pausa e se adapta após uma resposta.').replace('Illustrative workspace, not a live client system. Demo actions change only this browser’s local data. No CRM, messaging account or private database is connected.','Ambiente ilustrativo, sem conexão a sistemas de clientes. As ações alteram apenas dados locais deste navegador. Nenhum CRM, conta de mensagens ou banco privado está conectado.');}
Object.assign(dict,{'Interested reply recorded. Cadence paused automatically and a follow-up task created.':'Resposta de interesse registrada. Cadência pausada e tarefa de acompanhamento criada.','Demo activity logged. The contact reach count stays unique; the activity count increases.':'Atividade fictícia registrada. O alcance permanece único e o total de atividades aumenta.','Demo meeting recorded. The pipeline and meeting KPI have been updated.':'Reunião fictícia registrada. O indicador de reuniões foi atualizado.','Demo outreach logged (nothing sent).':'Abordagem fictícia registrada (nada foi enviado).','Interested reply simulated; cadence paused.':'Resposta de interesse simulada; cadência pausada.','Discovery meeting simulated (no calendar invitation sent).':'Reunião de discovery simulada (nenhum convite enviado).','Guided example: personalized outreach recorded (nothing sent).':'Exemplo guiado: abordagem personalizada registrada (nada enviado).','Guided example: interested reply; cadence paused.':'Exemplo guiado: resposta de interesse; cadência pausada.','Guided example: discovery meeting booked (no invitation sent).':'Exemplo guiado: reunião de discovery agendada (nenhum convite enviado).'});
function translatePage(){if(!isPT)return;document.querySelectorAll('option').forEach(o=>{if(!o.hasAttribute('value'))o.setAttribute('value',o.textContent)});const w=document.createTreeWalker(document.body,NodeFilter.SHOW_TEXT);let n;while(n=w.nextNode()){if(['SCRIPT','STYLE','TEXTAREA'].includes(n.parentElement?.tagName)||n.parentElement?.closest('textarea'))continue;const s=n.nodeValue.trim(),v=tr(s);if(s!==v)n.nodeValue=n.nodeValue.replace(s,v);}document.querySelectorAll('[placeholder],[aria-label]').forEach(el=>{for(const a of ['placeholder','aria-label'])if(el.hasAttribute(a)){const s=el.getAttribute(a),v=tr(s);if(v!==s)el.setAttribute(a,v);}});}
// A microtask observer translates newly rendered demo content, preserving form values.
if(isPT){const observer=new MutationObserver(()=>{observer.disconnect();translatePage();observer.observe(document.body,{subtree:true,childList:true,characterData:true});});translatePage();observer.observe(document.body,{subtree:true,childList:true,characterData:true});}
renderDeals();
const baselineDeals=JSON.parse(JSON.stringify(deals));
$('#reset').addEventListener('click',()=>{if(guideState)endGuide();leads=seed();save();render();deals.splice(0,deals.length,...JSON.parse(JSON.stringify(baselineDeals)));renderDeals();notify(copy('All fictional leads and opportunity scenarios have been restored.','Todos os leads fictícios e cenários de oportunidades foram restaurados.'));});
